import java.io.*;
import java.util.*;

public class Main {
    static final InputStream is = System.in;
    static final byte[] buf = new byte[1 << 16];
    static int len = 0, ptr = 0;

    static int rb() throws IOException {
        if (ptr == len) {
            len = is.read(buf, 0, buf.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return buf[ptr++];
    }

    static String next() throws IOException {
        int c = rb();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = rb();
        StringBuilder sb = new StringBuilder();
        while (c != -1 && c != ' ' && c != '\n' && c != '\r' && c != '\t') {
            sb.append((char) c);
            c = rb();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        int n = s.length();
        int[] prefix = new int[n + 1];
        for (int i = 0; i < n; i++) prefix[i + 1] = prefix[i] + (s.charAt(i) == '1' ? 1 : 0);
        long answer = 0;
        // k ones force length k*k + k.
        for (int k = 1; (long) k * k + k <= n; k++) {
            int length = k * k + k;
            for (int i = 0; i + length <= n; i++) if (prefix[i + length] - prefix[i] == k) answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"bufio"
	"fmt"
	"os"
)

var reader = bufio.NewReaderSize(os.Stdin, 1<<20)

func readToken() string {
	c, err := reader.ReadByte()
	for err == nil && (c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		c, err = reader.ReadByte()
	}
	var tok []byte
	for err == nil && !(c == ' ' || c == '\n' || c == '\r' || c == '\t') {
		tok = append(tok, c)
		c, err = reader.ReadByte()
	}
	return string(tok)
}

func main() {
	s := readToken()
	n := len(s)
	prefix := make([]int, n+1)
	for i := 0; i < n; i++ {
		prefix[i+1] = prefix[i]
		if s[i] == '1' {
			prefix[i+1]++
		}
	}
	answer := 0
	// k ones force length k*k + k.
	for k := 1; k*k+k <= n; k++ {
		length := k*k + k
		for i := 0; i+length <= n; i++ {
			if prefix[i+length]-prefix[i] == k {
				answer++
			}
		}
	}
	fmt.Println(answer)
}
